import React, { useState } from 'react';
import styles from './Counter.module.css';

interface CounterProps {
  initialValue?: number;
}

const Counter: React.FC<CounterProps> = ({ initialValue = 0 }) => {
  const [count, setCount] = useState<number>(initialValue);

  const increment = () => {
    setCount(prevCount => prevCount + 1);
  };

  const decrement = () => {
    setCount(prevCount => prevCount - 1);
  };

  const reset = () => {
    setCount(initialValue);
  };

  return (
    <div className={styles.container}>
      <p className={styles.count}>{count}</p>
      <div className={styles.buttons}>
        <button className={styles.button} onClick={increment}>Increment</button>
        <button className={styles.button} onClick={decrement}>Decrement</button>
        <button className={styles.button} onClick={reset}>Reset</button>
      </div>
    </div>
  );
};

export default Counter;

.container {
  text-align: center;
  padding: 20px;
  border: 1px solid #ccc;
  border-radius: 5px;
}

.count {
  font-size: 2em;
  margin-bottom: 10px;
}

.buttons {
  display: flex;
  justify-content: center;
  gap: 10px;
}

.button {
  padding: 10px 20px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-size: 1em;
}

.button:hover {
  background-color: #0056b3;
}

import { useState, useEffect, useRef, useCallback } from 'react';

interface UseFetchResult<T> {
  data: T | undefined;
  loading: boolean;
  error: Error | undefined;
}

function useFetch<T>(url: string | null): UseFetchResult<T> {
  const [data, setData] = useState<T | undefined>(undefined);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<Error | undefined>(undefined);
  const abortControllerRef = useRef<AbortController>(new AbortController());

  const fetchData = useCallback(async () => {
    if (!url) return;

    setLoading(true);
    setError(undefined);

    try {
      const response = await fetch(url, {
        signal: abortControllerRef.current.signal,
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      const json: T = await response.json();
      setData(json);
    } catch (e: any) {
      if (e.name === 'AbortError') {
        console.log('Fetch aborted');
      } else {
        setError(e as Error);
      }
    } finally {
      setLoading(false);
    }
  }, [url]);

  useEffect(() => {
    if (url) {
      fetchData();
    }

    return () => {
      abortControllerRef.current.abort();
    };
  }, [url, fetchData]);

  return { data, loading, error };
}

export { useFetch };

import React, { useReducer } from 'react';
import './App.css';

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

interface State {
  todos: Todo[];
}

const todoReducer = (
  state: State,
  action: {
    type: string;
    payload?: any;
  }
) => {
  switch (action.type) {
    case 'ADD':
      return {
        ...state,
        todos: [...state.todos, { id: Math.random(), text: action.payload, completed: false }],
      };
    case 'TOGGLE':
      return {
        ...state,
        todos: state.todos.map((todo) =>
          todo.id === action.payload ? { ...todo, completed: !todo.completed } : todo
        ),
      };
    case 'DELETE':
      return {
        ...state,
        todos: state.todos.filter((todo) => todo.id !== action.payload),
      };
    default:
      return state;
  }
};

function TodoApp() {
  const [state, dispatch] = useReducer(todoReducer, {
    todos: [],
  });

  const handleAddTodo = (text: string) => {
    dispatch({ type: 'ADD', payload: text });
  };

  const handleToggleTodo = (id: number) => {
    dispatch({ type: 'TOGGLE', payload: id });
  };

  const handleDeleteTodo = (id: number) => {
    dispatch({ type: 'DELETE', payload: id });
  };

  const activeTodos = state.todos.filter((todo) => !todo.completed);
  const completedTodos = state.todos.filter((todo) => todo.completed);

  return (
    <div className="App">
      <h1>Todo App</h1>
      <div>
        <input
          type="text"
          placeholder="Add todo"
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              handleAddTodo(e.target.value);
              e.target.value = '';
            }
          }}
        />
      </div>
      <div>
        <h2>Active:</h2>
        <ul>
          {activeTodos.map((todo) => (
            <li key={todo.id}>
              <input
                type="checkbox"
                checked={todo.completed}
                onChange={() => handleToggleTodo(todo.id)}
              />
              <span>{todo.text}</span>
              <button onClick={() => handleDeleteTodo(todo.id)}>Delete</button>
            </li>
          ))}
        </ul>
      </div>
      <div>
        <h2>Completed:</h2>
        <ul>
          {completedTodos.map((todo) => (
            <li key={todo.id}>
              <input
                type="checkbox"
                checked={todo.completed}
                onChange={() => handleToggleTodo(todo.id)}
                disabled
              />
              <span>{todo.text}</span>
              <button onClick={() => handleDeleteTodo(todo.id)}>Delete</button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export default TodoApp;

import { Request, Response, NextFunction } from 'express';

const API_KEYS = ['valid-api-key-1', 'valid-api-key-2']; // Replace with your actual API keys

export const authMiddleware = (req: Request, res: Response, next: NextFunction): void => {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({
      error: 'Authorization header missing',
    });
  }

  if (!authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Invalid authorization header format.  Expected "Bearer [API_KEY]"',
    });
  }

  const apiKey = authHeader.substring(7); // Remove "Bearer " prefix

  if (!API_KEYS.includes(apiKey)) {
    return res.status(401).json({
      error: 'Invalid API key',
    });
  }

  next(); // Proceed to the next middleware or route handler
};

import { setTimeout, clearTimeout } from 'timers';

interface DebounceOptions<T extends unknown[]> {
  leading?: boolean;
  trailing?: boolean;
  maxWait?: number;
}

interface DebouncedFunction<T extends unknown[]> {
  (...args: T):
    void;
  cancel(): void;
}

export function debounce<T extends unknown[]>(func: (...args: T) => void, delay: number, options: DebounceOptions<T> = {}): DebouncedFunction<T> {
  let timeoutId: NodeJS.Timeout | null = null;
  let lastArgs: T | null = null;
  let lastThis: any = null;

  const { leading = false, trailing = true, maxWait = delay } = options;

  const debounced = function (this: any, ...args: T) {
    lastArgs = args;
    lastThis = this;

    if (leading && !timeoutId) {
      func.apply(this, args);
    }

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (trailing && lastArgs) {
        func.apply(lastThis, lastArgs);
        lastArgs = null;
        lastThis = null;
      }
    }, delay);
  } as DebouncedFunction<T>;

  debounced.cancel = function () {
    clearTimeout(timeoutId);
    timeoutId = null;
    lastArgs = null;
    lastThis = null;
  };

  return debounced;
}
